package com.cyancoder.searchindex.service;import com.cyancoder.dynamiccore.runtime.*;import com.cyancoder.dynamiccore.store.mongo.DynamicEntityRecordDocument;import com.cyancoder.searchindex.entity.SearchSyncRunEntity;import com.cyancoder.searchindex.model.SearchAdminContracts.*;import com.cyancoder.searchindex.model.SearchIndexSyncResponse;import com.cyancoder.searchindex.repository.SearchSyncRunRepository;import java.time.Instant;import java.util.*;import org.springframework.data.domain.PageRequest;import org.springframework.data.domain.Sort;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class SearchAdminService{private final DynamicRuntimeService runtime;private final SearchIndexSyncService sync;private final SearchSyncRunRepository runs;private final TenantMembershipClient memberships;public SearchAdminService(DynamicRuntimeService r,SearchIndexSyncService s,SearchSyncRunRepository rr,TenantMembershipClient m){runtime=r;sync=s;runs=rr;memberships=m;}public List<IndexView>list(String t,String s,String a){scope(t,a);try{return runtime.listRecords("index-definition",new DynamicScope(t,s)).stream().map(this::view).toList();}catch(Exception e){return List.of();}}public IndexView get(String t,String s,String a,String k){scope(t,a);return view(runtime.getRecord("index-definition",k,new DynamicScope(t,s)));}
 public IndexView save(String t,String s,String a,String path,SaveIndexRequest r){scope(t,a);String k=required(path==null?r.indexKey():path,"indexKey");DynamicScope ds=new DynamicScope(t,s);ensure("index-definition",ds);ensure("search-document",ds);Map<String,Object>d=new LinkedHashMap<>();d.put("indexKey",k);d.put("source",Map.of("serviceKey",required(r.sourceServiceKey(),"sourceServiceKey"),"entityKey",required(r.sourceEntityKey(),"sourceEntityKey"),"entityType",required(r.sourceEntityType(),"sourceEntityType")));d.put("engine",n(r.engine(),"MONGO_PROJECTION"));d.put("status",n(r.status(),"ACTIVE"));d.put("searchableFields",list(r.searchableFields()));d.put("facetFields",list(r.facetFields()));d.put("sortableFields",list(r.sortableFields()));d.put("filterableFields",list(r.filterableFields()));d.put("suggestFields",list(r.suggestFields()));return view(runtime.submitMap("index-definition",k,d,true,ds));}
 @Transactional public SearchSyncRunView run(String t,String s,String a,String serviceKey,String entityKey,String idem){scope(t,a);if(idem==null||idem.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Idempotency-Key is required");return runs.findByTenantKeyAndIdempotencyKey(t,idem).map(this::runView).orElseGet(()->execute(t,s,a,serviceKey,entityKey,idem));}private SearchSyncRunView execute(String t,String s,String a,String sk,String ek,String idem){IndexView index=list(t,s,a).stream().filter(i->i.sourceServiceKey().equals(sk)&&i.sourceEntityKey().equals(ek)).findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"A matching index definition must be saved before sync"));SearchSyncRunEntity e=new SearchSyncRunEntity();e.setRunId(UUID.randomUUID().toString());e.setTenantKey(t);e.setSiteKey(s);e.setIndexKey(index.indexKey());e.setSourceServiceKey(sk);e.setSourceEntityKey(ek);e.setStatus("RUNNING");e.setActor(a);e.setIdempotencyKey(idem);e.setCreatedAt(Instant.now());e.setStartedAt(Instant.now());runs.save(e);try{SearchIndexSyncResponse result=sync.sync(sk,ek,new DynamicScope(t,s));e.setScannedCount(result.syncedCount());e.setSyncedCount(result.syncedCount());e.setStatus("SUCCEEDED");}catch(Exception ex){e.setStatus("FAILED");e.setErrorMessage(safe(ex.getMessage()));}e.setCompletedAt(Instant.now());return runView(runs.save(e));}
 public SearchSyncRunPage history(String t,String s,String a,int page,int size){scope(t,a);var p=runs.findByTenantKeyAndSiteKey(t,s,PageRequest.of(Math.max(0,page),Math.max(1,Math.min(size,100)),Sort.by(Sort.Direction.DESC,"createdAt")));return new SearchSyncRunPage(p.getContent().stream().map(this::runView).toList(),p.getNumber(),p.getSize(),p.getTotalElements());}public SearchIndexStats stats(String t,String s,String a,String k){scope(t,a);get(t,s,a,k);long count=runtime.listRecords("search-document",new DynamicScope(t,s)).stream().filter(r->{Object src=r.getData()==null?null:r.getData().get("source");if(!(src instanceof Map<?,?>m))return false;IndexView i=get(t,s,a,k);return Objects.equals(m.get("serviceKey"),i.sourceServiceKey())&&Objects.equals(m.get("entityKey"),i.sourceEntityKey());}).count();SearchSyncRunView last=runs.findFirstByTenantKeyAndSiteKeyAndIndexKeyOrderByCreatedAtDesc(t,s,k).map(this::runView).orElse(null);return new SearchIndexStats(k,count,last,last==null?"NOT_SYNCED":"SUCCEEDED".equals(last.status())?"AVAILABLE":"DEGRADED");}
 private IndexView view(DynamicEntityRecordDocument r){Map<String,Object>d=r.getData()==null?Map.of():r.getData();Map<?,?>src=d.get("source")instanceof Map<?,?>m?m:Map.of();return new IndexView(r.getRecordKey(),Objects.toString(src.get("serviceKey"),""),Objects.toString(src.get("entityKey"),""),Objects.toString(src.get("entityType"),""),Objects.toString(d.get("engine"),""),Objects.toString(d.get("status"),""),maps(d.get("searchableFields")),maps(d.get("facetFields")),maps(d.get("sortableFields")),maps(d.get("filterableFields")),maps(d.get("suggestFields")),r.getUpdatedAt());}private SearchSyncRunView runView(SearchSyncRunEntity e){return new SearchSyncRunView(e.getRunId(),e.getIndexKey(),e.getSourceServiceKey(),e.getSourceEntityKey(),e.getStatus(),e.getScannedCount(),e.getSyncedCount(),e.getFailedCount(),e.getErrorMessage(),e.getCreatedAt(),e.getStartedAt(),e.getCompletedAt());}private void ensure(String k,DynamicScope s){try{runtime.getDefinition(k,s);}catch(Exception e){runtime.createFromTemplate(k,k,s);}}private void scope(String t,String a){memberships.requireMembership(t,a);}private String required(String v,String f){if(v==null||v.isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,f+" is required");return v.trim();}private String n(String v,String d){return v==null||v.isBlank()?d:v;}private List<Map<String,Object>>list(List<Map<String,Object>>v){return v==null?List.of():v;}@SuppressWarnings("unchecked")private List<Map<String,Object>>maps(Object v){return v instanceof List<?>l?(List<Map<String,Object>>)l:List.of();}private String safe(String v){return v==null?"Search sync failed":v.substring(0,Math.min(1000,v.length()));}}
